#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int n1 = n / 2;
    vector<int> a1, a2;

    function<void(int, int)> generate_sums1 = [&](int i, int total) {
        if (i == n1) {
            a1.push_back(total);
        } else {
            generate_sums1(i + 1, (total + a[i]) % m);
            generate_sums1(i + 1, total);
        }
    };

    function<void(int, int)> generate_sums2 = [&](int i, int total) {
        if (i == n) {
            a2.push_back(total);
        } else {
            generate_sums2(i + 1, (total + a[i]) % m);
            generate_sums2(i + 1, total);
        }
    };

    generate_sums1(0, 0);
    generate_sums2(n1, 0);

    sort(a1.begin(), a1.end());

    int max_sum = 0;
    for (int val : a2) {
        int idx = (int)(lower_bound(a1.begin(), a1.end(), m - val) - a1.begin());
        int candidate;
        if (idx > 0) {
            candidate = a1[idx - 1] + val;
        } else {
            candidate = val;
        }
        if (candidate > max_sum) {
            max_sum = candidate;
        }
    }
    cout << max_sum << "\n";
    return 0;
}
